  m: { w: "Jeltje Alberts", d: "1759-06-16", p: "Leeuwarden", note: "ondertrouw bij het Gerecht; hij huisman in Huizum, zij uit Leeuwarden. Hervormd 01-07-1759 met attest naar Huizum; RK ingezegend 06-07-1759 in de statie Breedstraat" },
  kids: ["Gerben Gerbens Postma (ca. 1758 Huizum – 23-01-1822 Leeuwarden)", "Minke, Mincke (16-05-1764) · kw 207", "Albert, Albertus (gedoopt 21-06-1770)"],
